"""Planted test files: data that IS generated by a simple program or formula, so the search has something to find.
usage: python3 -I planted.py OUTDIR"""
import os, sys, numpy as np

out = sys.argv[1]; os.makedirs(out, exist_ok=True)

def eca(rule, width, steps, init):
    tab = np.array([(rule >> k) & 1 for k in range(8)], np.uint8)
    rows = np.zeros((steps, width), np.uint8); rows[0] = init
    for t in range(1, steps):
        r = rows[t - 1]
        l = np.concatenate([[0], r[:-1]]); rr = np.concatenate([r[1:], [0]])
        rows[t] = tab[(l << 2) | (r << 1) | rr]
    return np.packbits(rows.reshape(-1)).tobytes()

seed = np.zeros(4096, np.uint8); seed[2048] = 1
open(f'{out}/rule30_seed.bin', 'wb').write(eca(30, 4096, 2048, seed))                     # 1 MB
rnd = np.random.default_rng(3).integers(0, 2, 2048).astype(np.uint8)
open(f'{out}/rule110_random.bin', 'wb').write(eca(110, 2048, 4096, rnd))                  # 1 MB

# PRBS31 LFSR: s[i] = s[i-31] ^ s[i-28]
n = 8 * 2**20
s = np.zeros(n, np.uint8); s[:31] = np.random.default_rng(4).integers(0, 2, 31)
i = 31
while i < n:
    k = min(28, n - i)
    s[i:i + k] = s[i - 31:i - 31 + k] ^ s[i - 28:i - 28 + k]
    i += k
open(f'{out}/lfsr31.bin', 'wb').write(np.packbits(s).tobytes())                           # 1 MB

y, x = np.mgrid[0:1024, 0:1024]
open(f'{out}/xor_image.bin', 'wb').write(((x ^ y) & 255).astype(np.uint8).tobytes())    # 1 MB
img = ((x * x + y * y) >> 6) & 255
noise = np.random.default_rng(5).random(img.shape) < 0.05
img = np.where(noise, (img + np.random.default_rng(6).integers(-3, 4, img.shape)) & 255, img)
open(f'{out}/circles_noisy.bin', 'wb').write(img.astype(np.uint8).tobytes())             # 1 MB
print('ok', sorted(os.listdir(out)))
